 Y=np.c_[y,T]; results=[]
 def record(a,yy=Y,tag='',penalties=(.003,.015,.06,.25,1.)):
  a=standard(a);k=a@a.T
  for pen in penalties:
   e,p=out(k,yy,pen);results.append((e,p,tag,pen))
 record(np.c_[z,q,quad(z),quad(q),prod(z,q)],tag='mix')
 for i,u in enumerate(F):
