   record(np.c_[q,u,v,quad(q),prod(u,v)],tag=f'cross-{i}-{j}')
  u=standard(u);dist=np.maximum(0,((u*u).sum(1)[:,None]+(u*u).sum(1)-2*u@u.T));base=standard(np.c_[q,z,quad(q),quad(z)]); k0=base@base.T
  for ell in [1.5,2.5,4.5,7.]:
